"use client";

import { useEffect } from "react";

/*
 * Installs the service worker and reports whether the site is running offline.
 *
 * The service worker is only registered in a production build. In development it
 * would cache the dev bundle and serve stale code, which is the single most
 * confusing thing a service worker can do to you.
 *
 * `out/` is generated by `next build`, so on a static host the registration happens
 * once the real files exist. Everything the site needs offline is in the precache
 * list written by `fontend/scripts/build_sw.mjs`.
 */

declare global {
  interface Window {
    /** Set by this component so the UI can tell whether the app is installable. */
    __choloPwa?: { installed: boolean; offline: boolean };
  }
}

export function PwaBridge() {
  useEffect(() => {
    if (process.env.NODE_ENV !== "production") return;
    if (!("serviceWorker" in navigator)) return;

    const register = () => {
      navigator.serviceWorker
        .register("/sw.js", { scope: "/", updateViaCache: "none" })
        .then((registration) => {
          window.__choloPwa = { ...(window.__choloPwa ?? { installed: false, offline: false }), installed: true };
          // A new worker waits until the tabs using the old one are closed. That is
          // right for a page the passenger is mid-ride on, so nothing is forced here.
          registration.addEventListener("updatefound", () => {
            const installing = registration.installing;
            if (!installing) return;
            installing.addEventListener("statechange", () => {
              if (installing.state === "installed" && navigator.serviceWorker.controller) {
                window.dispatchEvent(new CustomEvent("cholo:update"));
              }
            });
          });
        })
        .catch(() => {
          // A blocked service worker (private mode, an http origin) is not fatal:
          // the site itself works, it just will not run without a signal.
        });
    };

    if (document.readyState === "complete") register();
    else window.addEventListener("load", register, { once: true });
    return () => window.removeEventListener("load", register);
  }, []);

  useEffect(() => {
    const sync = () => {
      window.__choloPwa = {
        installed: window.__choloPwa?.installed ?? false,
        offline: !window.navigator.onLine,
      };
    };
    sync();
    window.addEventListener("online", sync);
    window.addEventListener("offline", sync);
    return () => {
      window.removeEventListener("online", sync);
      window.removeEventListener("offline", sync);
    };
  }, []);

  return null;
}
